-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.check_employee_type_change(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Reads the request role: the dispatcher runs this as the owner, so
  -- current_user is never an API role.
  IF current_setting('role', true) IN ('anon', 'authenticated') IS NOT TRUE THEN
    RETURN;
  END IF;

  -- Moving a person to another employee type changes their access, so it goes
  -- through writeAccessGrants (audit, claims cache). Re-pointing a row at another
  -- person or company would carry its type (an Admin's) with it.
  IF p_operation = 'UPDATE' AND (
       (p_new->>'employeeTypeId') IS DISTINCT FROM (p_old->>'employeeTypeId')
       OR (p_new->>'id') IS DISTINCT FROM (p_old->>'id')
       OR (p_new->>'companyId') IS DISTINCT FROM (p_old->>'companyId')
     ) THEN
    RAISE EXCEPTION 'An employee''s type, person or company can only be changed by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- The type FK is on id alone, so nothing else stops a row naming another company's type.
  IF p_operation = 'INSERT' AND NOT EXISTS (
       SELECT 1 FROM "employeeType"
       WHERE id = p_new->>'employeeTypeId' AND "companyId" = p_new->>'companyId'
     ) THEN
    RAISE EXCEPTION 'An employee''s type must be one of the company''s'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Only the server removes a person (deactivation keeps the row); a delete and
  -- re-insert would otherwise move them to any type with no audit.
  IF p_operation = 'DELETE' THEN
    RAISE EXCEPTION 'An employee can only be removed by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Putting a person on the Admin type is an Admin's call.
  IF p_operation = 'INSERT'
     AND EXISTS (
       SELECT 1 FROM "employeeType"
       WHERE id = p_new->>'employeeTypeId'
         AND "companyId" = p_new->>'companyId'
         AND "systemType" = 'Admin'
     )
     -- With no page, access_level is Full only for the company's Admin type.
     AND util.access_level(auth.uid()::text, NULL, p_new->>'companyId', NULL) IS DISTINCT FROM 'Full' THEN
    RAISE EXCEPTION 'Only an Admin can add a person on the Admin type'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_employee_type_system_type(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Reads the request role, as check_employee_type_change does.
  IF current_setting('role', true) IN ('anon', 'authenticated') IS NOT TRUE THEN
    RETURN;
  END IF;

  -- The Admin system type is Full on every page, so setting or clearing a
  -- systemType is a server-only write.
  IF (p_operation = 'INSERT' AND p_new->>'systemType' IS NOT NULL)
     OR (p_operation = 'UPDATE'
         AND (p_new->>'systemType') IS DISTINCT FROM (p_old->>'systemType')) THEN
    RAISE EXCEPTION 'An employee type''s system type can only be set by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- A type moved to another company stops counting for the people on it: the
  -- Admin type moved away would leave the company with no Admin.
  IF p_operation = 'UPDATE' AND (
       (p_new->>'id') IS DISTINCT FROM (p_old->>'id')
       OR (p_new->>'companyId') IS DISTINCT FROM (p_old->>'companyId')
     ) THEN
    RAISE EXCEPTION 'An employee type''s company can only be changed by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_operation = 'DELETE' AND p_old->>'systemType' IS NOT NULL THEN
    RAISE EXCEPTION 'A system employee type can only be deleted by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_membership_system_group(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- A type, organisation or identity group mirrors who someone is, and shared
  -- documents trust it (the Admin type's group reads Admin-only documents), so
  -- only the interceptors that keep it in step write it. Their writes are nested
  -- inside another trigger; a direct API write is not.
  IF current_setting('role', true) IN ('anon', 'authenticated') IS NOT TRUE
     OR pg_trigger_depth() > 1 THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM "group"
    WHERE id IN (p_new->>'groupId', p_old->>'groupId')
      AND ("isEmployeeTypeGroup" OR "isCustomerTypeGroup" OR "isSupplierTypeGroup"
           OR "isCustomerOrgGroup" OR "isSupplierOrgGroup" OR "isIdentityGroup")
  ) THEN
    RAISE EXCEPTION 'The members of this group are kept by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_user_to_company_admin(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Removing an Admin from the company is an Admin's call, as making one is.
  IF p_operation <> 'DELETE'
     OR current_setting('role', true) IN ('anon', 'authenticated') IS NOT TRUE THEN
    RETURN;
  END IF;

  -- With no page, access_level is Full only for the company's Admin type.
  IF util.access_level(p_old->>'userId', NULL, p_old->>'companyId', NULL) = 'Full'
     AND util.access_level(auth.uid()::text, NULL, p_old->>'companyId', NULL) IS DISTINCT FROM 'Full' THEN
    RAISE EXCEPTION 'Only an Admin can remove an Admin from the company'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

